const iconPaths={home:'<path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/>',model:'<path d="M12 3v6M5 16v-4h14v4M12 9v7"/><rect x="9" y="1" width="6" height="5"/><rect x="2" y="16" width="6" height="6"/><rect x="9" y="16" width="6" height="6"/><rect x="16" y="16" width="6" height="6"/>',engineering:'<path d="M2 7q4-5 10 0t10 0M2 13q4-5 10 0t10 0M2 19q4-5 10 0t10 0"/>',configure:'<circle cx="12" cy="12" r="6"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4M4 4l3 3m10 10 3 3M4 20l3-3M17 7l3-3"/>',analysis:'<path d="M2 3h20v18H2zM5 16l5-6 4 3 5-7"/>',records:'<path d="M3 3h18v16l-4 3H3zM6 7h12M6 11h7M6 17l4-4 4 2 4-5"/>',reports:'<path d="M5 2h9l6 6v14H5zM14 2v6h6M8 12h9M8 16h9M8 19h6"/>'};
const links=[['home','首页'],['model','模型结构'],['engineering','工程原理'],['configure','工况配置'],['analysis','结果分析'],['records','运行与日志'],['reports','分析报告']];
const shell=document.createElement('aside');shell.id='tidal-shared-navigation';shell.setAttribute('aria-label','工作空间主导航');
shell.innerHTML=`<svg class="tidal-nav-edge" viewBox="0 0 256 1000" preserveAspectRatio="none" aria-hidden="true"><path d="M0 0H226C285 175 197 330 218 510S230 810 172 1000H0Z" fill="none" stroke="rgba(174,235,255,.42)" stroke-width="1.2"/><path d="M218 0C277 175 189 330 210 510S222 810 164 1000" fill="none" stroke="rgba(174,235,255,.13)" stroke-width="5"/></svg><a href="#home" class="tidal-nav-brand" aria-label="潮汐 TIDEFLOW · 首页"><img src="./assets/brand-lockup.svg?v=color-2" alt="潮汐 TIDEFLOW"></a><nav aria-label="页面导航">${links.map(([key,label])=>`<button type="button" data-page="${key}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.15" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[key]}</svg><span>${label}</span></button>`).join('')}</nav><footer><div class="tidal-nav-tools"><button type="button" data-nav-tool="ai">AI 助手</button><button type="button" data-nav-tool="guide">指南</button><button type="button" data-nav-tool="account">账户</button></div><p>潮境 · 深海视窗</p><small>TIDEFLOW<br>OCEAN EXPLORATION</small></footer>`;
const toggle=document.createElement('button');toggle.id='tidal-nav-toggle';toggle.type='button';toggle.setAttribute('aria-controls',shell.id);toggle.innerHTML='<span aria-hidden="true">☰</span><b>导航</b>';
const shade=document.createElement('button');shade.id='tidal-nav-shade';shade.type='button';shade.tabIndex=-1;shade.setAttribute('aria-label','关闭导航');
document.body.append(shell,toggle,shade);document.body.classList.add('tidal-navigation');
let open=false,desktopOpen=true;try{desktopOpen=localStorage.getItem('tidal-nav-desktop-open')!=='false';}catch{}const compact=matchMedia('(max-width:900px)');
function setOpen(value){open=value;document.body.classList.toggle('tidal-nav-open',open);document.body.classList.toggle('tidal-nav-closed',!open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'收起导航':'展开导航');toggle.querySelector('span').textContent=open?'‹':'☰';toggle.querySelector('b').textContent=open?'收起':'导航';shell.inert=!open;}
function syncPage(){
 const active=document.body.dataset.page,phase=document.querySelector('#page-configure .lab-experience')?.dataset.phase;
 const immersive=active==='configure'&&phase&&!['outside','loading'].includes(phase);
 document.body.classList.toggle('tidal-lab-immersive',Boolean(immersive));
 shell.hidden=Boolean(immersive);toggle.hidden=Boolean(immersive);shade.hidden=Boolean(immersive);
 for(const button of shell.querySelectorAll('[data-page]')){const selected=button.dataset.page===active;button.classList.toggle('is-current',selected);if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}
 // Give the landing page its full ocean view, independent of other pages' saved preference.
 if(immersive){setOpen(false);shell.inert=true;}else if(active==='home'||compact.matches)setOpen(false);else setOpen(desktopOpen);
}
toggle.onclick=()=>{setOpen(!open);if(!compact.matches){desktopOpen=open;try{localStorage.setItem('tidal-nav-desktop-open',String(open));}catch{}}};shade.onclick=()=>{setOpen(false);toggle.focus();};
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&compact.matches&&open){setOpen(false);toggle.focus();}});
shell.addEventListener('click',event=>{const tool=event.target.closest('[data-nav-tool]');if(tool){const id={ai:'side-ai',guide:'help-open',account:'account-launch'}[tool.dataset.navTool];document.getElementById(id)?.click();if(compact.matches)setOpen(false);}});
new MutationObserver(syncPage).observe(document.body,{subtree:true,attributes:true,attributeFilter:['data-page','data-phase']});compact.addEventListener('change',syncPage);syncPage();
